import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import pg from "pg";

const MIGRATIONS_SCHEMA = "drizzle";
const MIGRATIONS_TABLE = "__drizzle_migrations";
const MIGRATION_FILE_NAME = "migration.sql";
const MIGRATION_DATE_LENGTH = 14;
const MIGRATION_STATEMENT_SEPARATOR = "--> statement-breakpoint";
const MIGRATION_TIMESTAMP_PATTERN = /^\d{14}$/;
const migrationFolder = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "drizzle"
);

function requiredDatabaseUrl() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error("DATABASE_URL is required to run migrations.");
  }

  return databaseUrl;
}

function migrationTimestamp(directoryName) {
  const datePart = directoryName.slice(0, MIGRATION_DATE_LENGTH);

  if (!MIGRATION_TIMESTAMP_PATTERN.test(datePart)) {
    throw new Error(
      `Migration directory has no UTC timestamp: ${directoryName}`
    );
  }

  return Date.UTC(
    Number(datePart.slice(0, 4)),
    Number(datePart.slice(4, 6)) - 1,
    Number(datePart.slice(6, 8)),
    Number(datePart.slice(8, 10)),
    Number(datePart.slice(10, 12)),
    Number(datePart.slice(12, 14))
  );
}

function readMigrations() {
  if (!existsSync(migrationFolder)) {
    throw new Error("Committed migrations are missing from this image.");
  }

  return readdirSync(migrationFolder)
    .map((directoryName) => ({
      directoryName,
      path: join(migrationFolder, directoryName, MIGRATION_FILE_NAME),
    }))
    .filter((migration) => existsSync(migration.path))
    .sort((left, right) =>
      left.directoryName.localeCompare(right.directoryName)
    )
    .map(({ directoryName, path }) => {
      const source = readFileSync(path, "utf8");

      return {
        createdAt: migrationTimestamp(directoryName),
        hash: createHash("sha256").update(source).digest("hex"),
        statements: source
          .split(MIGRATION_STATEMENT_SEPARATOR)
          .filter((statement) => statement.trim().length > 0),
      };
    });
}

async function applyMigrations() {
  const client = new pg.Client({ connectionString: requiredDatabaseUrl() });

  try {
    await client.connect();
    await client.query(`CREATE SCHEMA IF NOT EXISTS ${MIGRATIONS_SCHEMA}`);
    await client.query(`
      CREATE TABLE IF NOT EXISTS ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE} (
        id SERIAL PRIMARY KEY,
        hash text NOT NULL,
        created_at bigint
      )
    `);

    const appliedResult = await client.query(
      `SELECT created_at FROM ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE}`
    );
    const appliedCreatedAt = new Set(
      appliedResult.rows.map((migration) => Number(migration.created_at))
    );

    for (const migration of readMigrations()) {
      if (appliedCreatedAt.has(migration.createdAt)) {
        continue;
      }

      await client.query("BEGIN");
      try {
        for (const statement of migration.statements) {
          await client.query(statement);
        }
        await client.query(
          `INSERT INTO ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE} (hash, created_at) VALUES ($1, $2)`,
          [migration.hash, migration.createdAt]
        );
        await client.query("COMMIT");
      } catch (error) {
        await client.query("ROLLBACK");
        throw error;
      }
    }
  } finally {
    await client.end();
  }
}

try {
  await applyMigrations();
} catch (error) {
  const message =
    error instanceof Error ? error.message : "Unknown migration failure.";
  process.stderr.write(`Migration failed: ${message}\n`);
  process.exitCode = 1;
}
#!/bin/sh

set -eu

IMAGE_TAG="${IMAGE_TAG:-chicken-tracking:smoke}"
NETWORK_NAME="chicken-tracking-smoke-$$"
DATABASE_NAME="chicken-tracking-database-$$"
APP_NAME="chicken-tracking-app-$$"
POSTGRES_URL="REDACTED"

cleanup() {
  docker rm --force "$APP_NAME" "$DATABASE_NAME" >/dev/null 2>&1 || true
  docker network rm "$NETWORK_NAME" >/dev/null 2>&1 || true
}

trap cleanup EXIT INT TERM

docker build --tag "$IMAGE_TAG" .
docker network create "$NETWORK_NAME" >/dev/null
docker run --detach --name "$DATABASE_NAME" --network "$NETWORK_NAME" \
  --env POSTGRES_DB=chicken_tracking \
  --env POSTGRES_PASSWORD=REDACTED \
  --env POSTGRES_USER=postgres \
  postgres:17-alpine >/dev/null

attempt=0
until docker exec "$DATABASE_NAME" pg_isready -U postgres -d chicken_tracking >/dev/null; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    echo "PostgreSQL did not become ready." >&2
    exit 1
  fi
  sleep 1
done

if docker run --rm "$IMAGE_TAG"; then
  echo "Container unexpectedly served without DATABASE_URL." >&2
  exit 1
fi

if docker run --rm --network "$NETWORK_NAME" \
  --env DATABASE_URL="REDACTED" \
  "$IMAGE_TAG"; then
  echo "Container unexpectedly served after a migration connection failure." >&2
  exit 1
fi

docker run --rm --network "$NETWORK_NAME" --env DATABASE_URL="$POSTGRES_URL" \
  "$IMAGE_TAG" migrate

docker run --detach --name "$APP_NAME" --network "$NETWORK_NAME" \
  --publish 127.0.0.1::3000 --env DATABASE_URL="$POSTGRES_URL" "$IMAGE_TAG" >/dev/null

attempt=0
until curl --fail --silent --show-error "http://127.0.0.1:$(docker port "$APP_NAME" 3000/tcp | sed 's/.*://')/health" \
  | grep --quiet '"status":"ok"'; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    docker logs "$APP_NAME" >&2
    echo "Container did not become healthy." >&2
    exit 1
  fi
  sleep 1
done

APP_HTTP_PORT="$(docker port "$APP_NAME" 3000/tcp | sed 's/.*://')"
curl --fail --silent --show-error "http://127.0.0.1:${APP_HTTP_PORT}/" | grep --quiet "Capture"
curl --fail --silent --show-error "http://127.0.0.1:${APP_HTTP_PORT}/plan" | grep --quiet "Plan"
node ./scripts/assembled-smoke.mjs "http://127.0.0.1:${APP_HTTP_PORT}"

docker stop "$DATABASE_NAME" >/dev/null
if curl --fail --silent "http://127.0.0.1:${APP_HTTP_PORT}/health"; then
  echo "Health remained ready after PostgreSQL connectivity was removed." >&2
  exit 1
fi

echo "Container smoke check passed."
#!/bin/sh

set -eu

case "${1:-serve}" in
  migrate)
    exec node ./scripts/migrate.mjs
    ;;
  serve)
    node ./scripts/migrate.mjs
    exec node ./.output/server/index.mjs
    ;;
  *)
    exec "$@"
    ;;
esac
FROM oven/bun:1.2.22-alpine AS build

WORKDIR /app

COPY package.json bun.lock ./
RUN bun install --frozen-lockfile

COPY . ./
RUN bun run build

FROM node:24-alpine AS runtime

WORKDIR /app

ENV NODE_ENV=production
ENV HOST=0.0.0.0
ENV PORT=3000

COPY --from=build /app/.output ./.output
COPY --from=build /app/drizzle ./drizzle
COPY --from=build /app/scripts/container-start.sh ./scripts/container-start.sh
COPY --from=build /app/scripts/migrate.mjs ./scripts/migrate.mjs

RUN mv ./.output/server/node_modules ./node_modules \
  && chmod 555 ./scripts/container-start.sh

USER node

EXPOSE 3000

HEALTHCHECK --interval=30s --timeout=5s --start-period=10s --retries=3 \
  CMD node -e 'fetch("http://127.0.0.1:3000/health").then((response) => process.exit(response.ok ? 0 : 1)).catch(() => process.exit(1))'

ENTRYPOINT ["./scripts/container-start.sh"]
CMD ["serve"]
